#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxSubarraySum(std::vector<int>& nums, int m, int k) {
        int n = nums.size();
        if (m > n) return 0;
        long long best = -1e18;
        for (int i = 0; i <= n - m; ++i) {
            std::vector<int> inside(nums.begin() + i, nums.begin() + i + m);
            std::vector<int> outside;
            outside.insert(outside.end(), nums.begin(), nums.begin() + i);
            outside.insert(outside.end(), nums.begin() + i + m, nums.end());
            std::sort(inside.begin(), inside.end());
            std::sort(outside.rbegin(), outside.rend());
            long long cur = 0;
            for (int x : inside) cur += x;
            int swaps = std::min({k, (int)inside.size(), (int)outside.size()});
            for (int s = 0; s < swaps; ++s) {
                if (outside[s] > inside[s]) cur += (outside[s] - inside[s]);
                else break;
            }
            best = std::max(best, cur);
        }
        return best;
    }
};

class Solution {
    public long maxSubarraySum(int[] nums, int k, int m) {
        int n = nums.length;
        long current = 0;
        for (int i = 0; i < k; i++) current += nums[i];
        long maxSum = current;
        for (int i = k; i < n; i++) {
            current += nums[i] - nums[i - k];
            if (current > maxSum) maxSum = current;
        }
        return maxSum;
    }
}

